using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change: HasData no longer accepts navigation/temporal values
        // that change on every migration. Use a fixed seed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; }

}

// --- Cosmos DB context demonstrating EF9 breaking-change fixes ---

class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
        => options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "ShopDb");

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF9 breaking change #1: Discriminator property is now "$type" by default.
        // Existing documents use "Discriminator". Override to maintain compatibility.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator")
            .HasValue<Product>("Product");

        modelBuilder.Entity<Product>().ToContainer("Products");
    }

    // EF9 breaking change #2: Synchronous I/O on Cosmos DB provider now throws
    // InvalidOperationException. All queries must use async methods.
    public async Task<List<Product>> GetExpensiveProductsAsync(decimal minPrice)
    {
        return await Products
            .Where(p => p.Price >= minPrice)
            .ToListAsync();
    }
}

class Product
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
    public decimal Price { get; set; }
}

